pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _logger, bool _status) public {
        // 1. The reference enforces an onlyOwner constraint for setApprovedLogger.
        //    We must ensure the call succeeds, so we prank the owner.
        //    The owner is the deployer of C, which is this test contract.
        //    We need the owner to first approve a logger so we can observe the change.
        //    We restrict the domain: the logger must not be the owner (to keep the test meaningful)
        //    and we need a valid initial state.
        vm.assume(_logger != address(this));

        // Owner sets the logger to the opposite of the target status to create a baseline difference
        vm.startPrank(address(this));
        c.setApprovedLogger(_logger, !_status);
        vm.stopPrank();

        // Now call setApprovedLogger with the fuzzed status
        vm.prank(address(this));
        c.setApprovedLogger(_logger, _status);

        // Assert: the approved status of the logger must equal the provided status
        bool actualStatus = c.approvedToLog(_logger);
        assertTrue(actualStatus == _status);
    }
}

