import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address logger1, address logger2, uint8 boolEitherIsContractOwner) public {
        vm.assume(logger1 != logger2);
        vm.assume(logger1 != address(this));
        vm.assume(logger2 != address(this));
        vm.assume(logger1 != address(0));
        vm.assume(logger2 != address(0));
        // Make the owner either logger1 or logger2 with 50% probability to fuzz over the owner identity
        address owner = boolEitherIsContractOwner % 2 == 0 ? logger1 : logger2;
        // Deploy a helper to set the contract owner to 'owner', since there's no public setter for _contractOwner.
        // We deploy a one-shot caller who will set up the owner via the constructor dev.
        // Wait, the contract has no public owner setter. We use deployCode? No.
        // Actually we can just deploy c and the owner is whoever deployed it, which is this test contract.
        // To test the property, the owner is the test contract itself (address(this)), and we fuzz the loggers.
        // The property must hold regardless of who the owner is.
        // The only way to call setApprovedLogger is as the owner. So we must be the owner.
        // We will use logger1 and logger2 as distinct loggers, and setApprovedLogger for logger1 to true.

        // The owner is the test contract (deployer of C).
        // Ensure logger1 and logger2 are not the owner.
        vm.assume(logger1 != address(this));
        vm.assume(logger2 != address(this));

        // Call setApprovedLogger for logger1 with status true
        c.setApprovedLogger(logger1, true);

        // Now logger1 should be approved, logger2 should remain false
        bool logger1Approved = c.approvedLoggers(logger1);
        bool logger2Approved = c.approvedLoggers(logger2);

        // The reference contract satisfies: logger1Approved == true && logger2Approved == false
        // The mutant never updates the mapping, so both remain false.
        assertTrue(logger1Approved && !logger2Approved);
    }
}

