pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address logger, bool status) public {
        vm.assume(logger != address(0));
        uint256 beforeCount = countApproved();
        c.setApprovedLogger(logger, status);
        uint256 afterCount = countApproved();
        assertTrue(afterCount - beforeCount <= 1);
    }
    function countApproved() internal returns (uint256 count) {
        count = 0;
        uint256 start = 0x0000000000000000000000000000000000000001;
        uint256 end = 0x0000000000000000000000000000000000000010;
        for (uint256 i = start; i <= end; i++) {
            if (c.approvedToLog(address(uint160(i)))) count++;
        }
        if (c.approvedToLog(address(0))) count++;
    }
}

